import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 공유 방식 허용값
const SHARE_METHODS = ['NOTE', 'EMAIL'];
// 가정: 쪽지 안내 문구 (문서 제목을 뒤에 붙인다)
const NOTE_PREFIX = '문서가 공유되었습니다: ';
// 가정: 외부 메일 연동은 명세에 없으므로 이메일은 발송 대기 상태로 기록만 한다
const STATUS_NOTE = 'SENT';
const STATUS_EMAIL = 'QUEUED';

@Controller('api/v1')
export class FnSfr04105Controller {
  @Post('/office-documents/:officeDocumentId/share')
  @HttpCode(200)
  async shareOfficeDocument(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const documentId = req.params['officeDocumentId'];
    const shareMethod = typeof data['shareMethod'] === 'string' ? data['shareMethod'] : '';
    if (!SHARE_METHODS.includes(shareMethod)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '공유 방식은 쪽지 또는 이메일 중에서 선택해 주세요.');
    }
    if (!/^\d+$/.test(documentId)) {
      throw new ApiError(404, 'OFFICE_DOCUMENT_NOT_FOUND', '공유할 문서를 찾을 수 없습니다.');
    }
    const targets = data['targets'];
    if (!Array.isArray(targets) || targets.length === 0) {
      throw new ApiError(422, 'SHARE_TARGET_REQUIRED', '공유 대상자와 권한을 지정해 주세요.');
    }
    const parsed: { employeeId: string; canEdit: boolean }[] = [];
    for (const t of targets) {
      if (typeof t !== 'object' || t === null || Array.isArray(t)) {
        throw new ApiError(422, 'SHARE_TARGET_REQUIRED', '공유 대상자와 권한을 지정해 주세요.');
      }
      const rec = t as Record<string, unknown>;
      const empId = String(rec['employeeId'] ?? '');
      if (!/^\d+$/.test(empId) || typeof rec['canEdit'] !== 'boolean') {
        throw new ApiError(422, 'SHARE_TARGET_REQUIRED', '공유 대상자와 권한을 지정해 주세요.');
      }
      parsed.push({ employeeId: empId, canEdit: rec['canEdit'] as boolean });
    }
    return transaction(async (db) => {
      const docs = await db.query(
        'SELECT title FROM office_document WHERE office_document_id = CAST(:documentId AS bigint)',
        { documentId },
      );
      if (docs.length === 0) {
        throw new ApiError(404, 'OFFICE_DOCUMENT_NOT_FOUND', '공유할 문서를 찾을 수 없습니다.');
      }
      const title = String(docs[0]['title']);
      for (const t of parsed) {
        const emp = await db.query(
          "SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint) AND employment_status = '재직자'",
          { employeeId: t.employeeId },
        );
        if (emp.length === 0) {
          throw new ApiError(422, 'INVALID_SHARE_PERMISSION', '그룹웨어 사용자가 아닌 대상은 공유할 수 없습니다.');
        }
      }
      for (const t of parsed) {
        await db.execute(
          'INSERT INTO office_document_share (office_document_id, employee_id, can_edit, created_at, updated_at) ' +
            'VALUES (CAST(:documentId AS bigint), CAST(:employeeId AS bigint), :canEdit, now(), now()) ' +
            'ON CONFLICT (office_document_id, employee_id) DO UPDATE SET can_edit = EXCLUDED.can_edit, updated_at = now()',
          { documentId, employeeId: t.employeeId, canEdit: t.canEdit },
        );
      }
      if (shareMethod === 'NOTE') {
        await db.query(
          'INSERT INTO messenger_message (sender_id, message_type, content, sent_at, created_at, updated_at) ' +
            "VALUES (CAST(:userId AS bigint), 'NOTE', :content, now(), now(), now()) RETURNING messenger_message_id AS \"messengerMessageId\"",
          { userId: user.id, content: NOTE_PREFIX + title },
        );
      }
      const granted = await db.query(
        'SELECT employee_id AS "employeeId", can_edit AS "canEdit" FROM office_document_share ' +
          'WHERE office_document_id = CAST(:documentId AS bigint) ORDER BY office_document_share_id',
        { documentId },
      );
      return {
        shared: true,
        grantedPermissions: granted,
        notificationStatus: shareMethod === 'NOTE' ? STATUS_NOTE : STATUS_EMAIL,
      };
    });
  }
}

