import { useState } from 'react';
import {
  call,
  Band,
  Drawer,
  Form,
  Field,
  Select,
  LookupSelect,
  RefName,
  DataTable,
  Badge,
  NumberInput,
  type PageProps,
  type Row,
} from '../kit';

interface Target {
  employeeId: number | string;
  canEdit: string;
}

export default function FnSfr04105Page({ role, notify }: PageProps) {
  const [open, setOpen] = useState(false);
  const [documentId, setDocumentId] = useState<number | string>('');
  const [shareMethod, setShareMethod] = useState('');
  const [targets, setTargets] = useState<Target[]>([{ employeeId: '', canEdit: 'false' }]);
  const [results, setResults] = useState<Row[]>([]);

  const reset = () => {
    setDocumentId('');
    setShareMethod('');
    setTargets([{ employeeId: '', canEdit: 'false' }]);
  };

  const updateTarget = (index: number, patch: Partial<Target>) => {
    setTargets(targets.map((t, i) => (i === index ? { ...t, ...patch } : t)));
  };

  const submit = async () => {
    if (documentId === '') throw new Error('공유할 문서를 선택해 주세요.');
    if (!shareMethod) throw new Error('공유 방식을 선택해 주세요.');
    const filled = targets.filter((t) => t.employeeId !== '');
    if (filled.length === 0) throw new Error('공유 대상자를 한 명 이상 선택해 주세요.');
    const res = await call<Row>('POST', '/office-documents/' + documentId + '/share', role, {
      shareMethod,
      targets: filled.map((t) => ({ employeeId: t.employeeId, canEdit: t.canEdit === 'true' })),
    });
    const granted = (res['grantedPermissions'] as Row[]) || [];
    setResults(
      granted.map((g) => ({
        documentId,
        employeeId: g['employeeId'],
        canEdit: g['canEdit'] ? '수정 가능' : '열람만 가능',
        notificationStatus: res['notificationStatus'],
      })),
    );
    notify('문서를 공유했습니다.');
    setOpen(false);
    reset();
  };

  return (
    <div className="doc">
      <section className="box">
        <h2>문서 공유 결과</h2>
        <Band total={results.length}>
          <button
            onClick={() => {
              reset();
              setOpen(true);
            }}
          >
            문서 공유
          </button>
        </Band>
        <DataTable
          columns={[
            {
              key: 'documentId',
              label: '웹 오피스 문서',
              render: (r) => <RefName table="office_document" role={role} value={r['documentId']} />,
            },
            {
              key: 'employeeId',
              label: '공유 대상자',
              render: (r) => <RefName table="employee" role={role} value={r['employeeId']} />,
            },
            { key: 'canEdit', label: '부여 권한' },
            {
              key: 'notificationStatus',
              label: '공유 안내 발송 결과',
              render: (r) => <Badge value={r['notificationStatus']} />,
            },
          ]}
          rows={results}
          empty="아직 공유한 문서가 없습니다. 문서 공유 버튼을 눌러 시작해 주세요."
        />
      </section>
      {open && (
        <Drawer title="문서 공유" onClose={() => setOpen(false)}>
          <Form
            onSubmit={submit}
            submit="공유"
            note="공유하면 대상자에게 안내가 발송되고 대상자의 공유 문서함에 반영됩니다."
          >
            <Field label="웹 오피스 문서" required wide>
              <LookupSelect
                table="office_document"
                role={role}
                value={documentId}
                onChange={setDocumentId}
                placeholder="문서 선택"
              />
            </Field>
            <Field label="공유 방식" required wide>
              <Select
                value={shareMethod}
                onChange={setShareMethod}
                options={[
                  ['NOTE', '쪽지'],
                  ['EMAIL', '이메일'],
                ]}
              />
            </Field>
            {targets.map((t, i) => (
              <div key={i}>
                <Field label="공유 대상자" required wide>
                  <LookupSelect
                    table="employee"
                    role={role}
                    value={t.employeeId}
                    onChange={(v) => updateTarget(i, { employeeId: v })}
                    placeholder="대상자 선택"
                  />
                </Field>
                <Field label="수정 권한 여부" wide hint="열람 권한은 공유하면 함께 부여됩니다.">
                  <Select
                    value={t.canEdit}
                    onChange={(v) => updateTarget(i, { canEdit: v })}
                    options={[
                      ['false', '열람만 가능'],
                      ['true', '열람 및 수정 가능'],
                    ]}
                    placeholder="열람만 가능"
                  />
                </Field>
              </div>
            ))}
            <button
              type="button"
              className="ghost"
              onClick={() => setTargets([...targets, { employeeId: '', canEdit: 'false' }])}
            >
              대상자 추가
            </button>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
